// N2 grammar points in teaching order (unit numbers refer to the 60 N2 units). Part 1: units 1–30.
import { GRAMMAR2 } from './n2-grammar-src-2.mjs';

const GRAMMAR1 = [
  { id: 'ue-de', unit: 1, title: '〜上で', pattern: '[V-た / N の] 上で', summary: 'after doing; upon', explanation: '上で after a past verb or N の means "after (carefully) doing X, then Y". It implies the first step is a basis for the second.',
    ex: [['よく考えた上で、返事をします。', 'よくかんがえたうえで、へんじをします。', 'yoku kangaeta ue de, henji o shimasu.', 'I will reply after thinking it over carefully.'], ['内容を確認した上で、契約してください。', 'ないようをかくにんしたうえで、けいやくしてください。', 'naiyou o kakunin shita ue de, keiyaku shite kudasai.', 'Please sign the contract after checking the contents.'], ['相談の上で決めましょう。', 'そうだんのうえできめましょう。', 'soudan no ue de kimemashou.', 'Let us decide after consulting.']],
    mistakes: ['Dictionary form + 上で means "in the process of" (仕事をする上で), not "after".'],
    exercises: [{ type: 'fill', prompt: '家族と話し合った＿、留学を決めた。', answer: '上で', choices: ['上で', '上に', '上は'], why: 'After doing: 〜た上で.' }] },
  { id: 'ue-ni', unit: 1, title: '〜上に', pattern: '[plain / N の / な-adj な] 上に', summary: 'in addition; on top of', explanation: '上に adds a second point in the same direction: good plus good, or bad plus bad.',
    ex: [['この店は安い上に、料理もおいしい。', 'このみせはやすいうえに、りょうりもおいしい。', 'kono mise wa yasui ue ni, ryouri mo oishii.', 'This restaurant is cheap, and on top of that the food is good.'], ['道に迷った上に、雨まで降ってきた。', 'みちにまよったうえに、あめまでふってきた。', 'michi ni mayotta ue ni, ame made futte kita.', 'I got lost, and on top of that it started raining.'], ['彼は親切な上に、仕事も速い。', 'かれはしんせつなうえに、しごともはやい。', 'kare wa shinsetsu na ue ni, shigoto mo hayai.', 'He is kind, and moreover quick at his work.']],
    mistakes: ['Do not mix a good point with a bad one after 上に.'],
    exercises: [{ type: 'fill', prompt: 'このアパートは駅から近い＿、家賃も安い。', answer: '上に', choices: ['上に', '上で', '上は'], why: 'In addition: 上に.' }] },
  { id: 'ippou-da', unit: 2, title: '〜一方だ', pattern: '[V-dictionary] 一方だ', summary: 'keeps on (changing in one direction)', explanation: '一方だ after a verb of change says the change continues in one direction only, often with concern.',
    ex: [['物価は上がる一方だ。', 'ぶっかはあがるいっぽうだ。', 'bukka wa agaru ippou da.', 'Prices keep going up.'], ['都市の人口は増える一方です。', 'としのじんこうはふえるいっぽうです。', 'toshi no jinkou wa fueru ippou desu.', 'The population of the cities keeps increasing.'], ['祖父の病気は悪くなる一方だった。', 'そふのびょうきはわるくなるいっぽうだった。', 'sofu no byouki wa waruku naru ippou datta.', 'My grandfather\'s illness just kept getting worse.']],
    mistakes: ['Only with verbs of change (増える, 減る, 悪くなる …).'],
    exercises: [{ type: 'fill', prompt: '仕事が忙しくて、疲れはたまる＿。', answer: '一方だ', choices: ['一方だ', '一方で', 'ばかりか'], why: 'One-directional change: 一方だ.' }] },
  { id: 'ippou-de', unit: 2, title: '〜一方（で）', pattern: '[plain] 一方（で）', summary: 'on the one hand … on the other', explanation: '一方（で） links two contrasting sides of the same topic or person.',
    ex: [['彼は厳しい一方で、優しいところもある。', 'かれはきびしいいっぽうで、やさしいところもある。', 'kare wa kibishii ippou de, yasashii tokoro mo aru.', 'He is strict, but on the other hand he has a kind side.'], ['輸出が増える一方で、輸入は減っている。', 'ゆしゅつがふえるいっぽうで、ゆにゅうはへっている。', 'yushutsu ga fueru ippou de, yunyuu wa hette iru.', 'While exports are increasing, imports are falling.'], ['都市は便利な一方、生活費が高い。', 'としはべんりないっぽう、せいかつひがたかい。', 'toshi wa benri na ippou, seikatsuhi ga takai.', 'Cities are convenient, but on the other hand the cost of living is high.']],
    mistakes: ['一方だ (keeps …ing) and 一方で (contrast) are different patterns.'],
    exercises: [{ type: 'fill', prompt: '便利になった＿、新しい問題も生まれた。', answer: '一方で', choices: ['一方で', '一方だ', '上で'], why: 'Contrast: 一方で.' }] },
  { id: 'uchi-ni', unit: 3, title: '〜うちに', pattern: '[V-dictionary / V-ている / V-ない / い-adj / N の] うちに', summary: 'while; before (a change)', explanation: 'うちに means "while a state lasts" or, with ない, "before something happens". It often implies you should act before it is too late.',
    ex: [['温かいうちに食べてください。', 'あたたかいうちにたべてください。', 'atatakai uchi ni tabete kudasai.', 'Please eat it while it is warm.'], ['暗くならないうちに帰ろう。', 'くらくならないうちにかえろう。', 'kuraku naranai uchi ni kaerou.', 'Let\'s go home before it gets dark.'], ['音楽を聞いているうちに眠ってしまった。', 'おんがくをきいているうちにねむってしまった。', 'ongaku o kiite iru uchi ni nemutte shimatta.', 'While listening to music I fell asleep.']],
    mistakes: ['間に is neutral timing; うちに adds "before the chance is gone".'],
    exercises: [{ type: 'fill', prompt: '雨が降らない＿、洗濯物を取り込もう。', answer: 'うちに', choices: ['うちに', '間', 'ところに'], why: 'Before a change: ないうちに.' }] },
  { id: 'eru-enai', unit: 3, title: '〜得る・〜得ない', pattern: '[V-stem] 得る (うる・える) / 得ない (えない)', summary: 'can; possibly / cannot possibly', explanation: 'A formal possibility: 考え得る "conceivable", あり得ない "impossible". Not about personal ability.',
    ex: [['そんなことはあり得ない。', 'そんなことはありえない。', 'sonna koto wa arienai.', 'That is impossible.'], ['事故はいつでも起こり得る。', 'じこはいつでもおこりうる。', 'jiko wa itsu demo okoriuru.', 'Accidents can happen at any time.'], ['考え得る方法は全部試した。', 'かんがえうるほうほうはぜんぶためした。', 'kangaeuru houhou wa zenbu tameshita.', 'I tried every conceivable method.']],
    mistakes: ['For "I can" (ability), use the potential form, not 得る.'],
    exercises: [{ type: 'fill', prompt: '地震はどこでも起こり＿。', answer: '得る', choices: ['得る', 'かねる', 'きれる'], why: 'Possibility: 起こり得る.' }] },
  { id: 'osore-ga-aru', unit: 4, title: '〜おそれがある', pattern: '[V-dictionary / N の] おそれがある', summary: 'there is a risk that', explanation: 'A formal warning that something bad may happen, used in news and notices.',
    ex: [['台風が上陸するおそれがあります。', 'たいふうがじょうりくするおそれがあります。', 'taifuu ga jouriku suru osore ga arimasu.', 'There is a risk that the typhoon will make landfall.'], ['この薬は副作用のおそれがある。', 'このくすりはふくさようのおそれがある。', 'kono kusuri wa fukusayou no osore ga aru.', 'This medicine carries a risk of side effects.'], ['情報が漏れるおそれがあるので注意してください。', 'じょうほうがもれるおそれがあるのでちゅういしてください。', 'jouhou ga moreru osore ga aru node chuui shite kudasai.', 'Please be careful, as there is a risk of information leaking.']],
    mistakes: ['Only for undesirable outcomes.'],
    exercises: [{ type: 'fill', prompt: '川の水があふれる＿。', answer: 'おそれがある', choices: ['おそれがある', 'ことがある', 'わけがある'], why: 'Risk of a bad event: おそれがある.' }] },
  { id: 'ka-nai-ka-no-uchi-ni', unit: 4, title: '〜か〜ないかのうちに', pattern: '[V-dictionary / V-た] か [V-ない] かのうちに', summary: 'the moment; barely … when', explanation: 'Two events almost overlap: the second starts before the first is quite finished.',
    ex: [['ベルが鳴るか鳴らないかのうちに、学生は教室を出た。', 'ベルがなるかならないかのうちに、がくせいはきょうしつをでた。', 'beru ga naru ka naranai ka no uchi ni, gakusei wa kyoushitsu o deta.', 'The moment the bell rang, the students left the classroom.'], ['家に着くか着かないかのうちに、雨が降り出した。', 'いえにつくかつかないかのうちに、あめがふりだした。', 'ie ni tsuku ka tsukanai ka no uchi ni, ame ga furidashita.', 'I had barely reached home when it started to rain.'], ['横になるかならないかのうちに眠ってしまった。', 'よこになるかならないかのうちにねむってしまった。', 'yoko ni naru ka naranai ka no uchi ni nemutte shimatta.', 'I fell asleep the moment I lay down.']],
    mistakes: ['The same verb appears twice: 出るか出ないか.'],
    exercises: [{ type: 'fill', prompt: '店が開くか＿かのうちに、客が入ってきた。', answer: '開かない', choices: ['開かない', '開いた', '開く'], why: 'Vるか Vないかのうちに.' }] },
  { id: 'kake', unit: 5, title: '〜かけ・〜かける', pattern: '[V-stem] かけの N / かける', summary: 'half-done; about to', explanation: 'かけ marks an action begun but not finished (読みかけの本), or on the verge of happening (死にかける).',
    ex: [['読みかけの本が机の上にある。', 'よみかけのほんがつくえのうえにある。', 'yomikake no hon ga tsukue no ue ni aru.', 'There is a half-read book on the desk.'], ['彼は何か言いかけて、やめた。', 'かれはなにかいいかけて、やめた。', 'kare wa nanika iikakete, yameta.', 'He started to say something, then stopped.'], ['火が消えかけている。', 'ひがきえかけている。', 'hi ga kiekakete iru.', 'The fire is about to go out.']],
    mistakes: ['話しかける (to address someone) is a separate word.'],
    exercises: [{ type: 'fill', prompt: '食べ＿のパンを捨てないでください。', answer: 'かけ', choices: ['かけ', 'きり', 'がち'], why: 'Half-eaten: 食べかけ.' }] },
  { id: 'gatai', unit: 5, title: '〜がたい', pattern: '[V-stem] がたい', summary: 'hard to (emotionally or logically)', explanation: 'がたい: difficult to do because it is unthinkable or unbearable, not physically hard. 信じがたい, 理解しがたい, 忘れがたい.',
    ex: [['彼が嘘をついたとは信じがたい。', 'かれがうそをついたとはしんじがたい。', 'kare ga uso o tsuita to wa shinjigatai.', 'It is hard to believe that he lied.'], ['その決定は理解しがたい。', 'そのけっていはりかいしがたい。', 'sono kettei wa rikai shigatai.', 'That decision is hard to understand.'], ['忘れがたい思い出になった。', 'わすれがたいおもいでになった。', 'wasuregatai omoide ni natta.', 'It became an unforgettable memory.']],
    mistakes: ['Physical difficulty is にくい (読みにくい), not がたい.'],
    exercises: [{ type: 'fill', prompt: 'あの優しい人が犯人だとは信じ＿。', answer: 'がたい', choices: ['がたい', 'にくい', 'づらい'], why: 'Unthinkable: 信じがたい.' }] },
  { id: 'gachi', unit: 6, title: '〜がちだ', pattern: '[V-stem / N] がちだ', summary: 'tends to (undesirably)', explanation: 'がち: a tendency that is usually negative. 遅れがち, 病気がち, 忘れがち.',
    ex: [['冬は風邪を引きがちだ。', 'ふゆはかぜをひきがちだ。', 'fuyu wa kaze o hikigachi da.', 'In winter one tends to catch colds.'], ['最近、約束を忘れがちで困る。', 'さいきん、やくそくをわすれがちでこまる。', 'saikin, yakusoku o wasuregachi de komaru.', 'Lately I tend to forget appointments, which is a problem.'], ['子供のころは病気がちだった。', 'こどものころはびょうきがちだった。', 'kodomo no koro wa byoukigachi datta.', 'As a child I was often ill.']],
    mistakes: ['Not for good tendencies.'],
    exercises: [{ type: 'fill', prompt: '忙しいと、食事が不規則になり＿だ。', answer: 'がち', choices: ['がち', 'げ', 'かけ'], why: 'Negative tendency: がち.' }] },
  { id: 'ka-to-omou-to', unit: 6, title: '〜かと思うと・〜かと思ったら', pattern: '[V-た] かと思うと / かと思ったら', summary: 'no sooner … than', explanation: 'Right after one thing happens, something surprising or contrasting follows. Not used for the speaker\'s own actions.',
    ex: [['空が暗くなったかと思うと、大雨が降り出した。', 'そらがくらくなったかとおもうと、おおあめがふりだした。', 'sora ga kuraku natta ka to omou to, ooame ga furidashita.', 'No sooner had the sky darkened than heavy rain began.'], ['赤ん坊は泣いたかと思ったら、もう笑っている。', 'あかんぼうはないたかとおもったら、もうわらっている。', 'akanbou wa naita ka to omottara, mou waratte iru.', 'The baby was crying one moment and is already laughing the next.'], ['帰ってきたかと思うと、また出かけた。', 'かえってきたかとおもうと、またでかけた。', 'kaette kita ka to omou to, mata dekaketa.', 'He had just come home when he went out again.']],
    mistakes: ['Cannot describe what the speaker plans to do.'],
    exercises: [{ type: 'fill', prompt: '弟は宿題を始めた＿、もう遊びに行ってしまった。', answer: 'かと思うと', choices: ['かと思うと', 'かのうちに', 'かのように'], why: 'Quick surprising change: かと思うと.' }] },
  { id: 'kara-koso', unit: 7, title: '〜からこそ', pattern: '[plain] からこそ', summary: 'precisely because', explanation: 'こそ emphasises the reason: not for any other reason, but exactly this one. Often ends with のだ.',
    ex: [['あなただからこそ、頼みたいのです。', 'あなただからこそ、たのみたいのです。', 'anata da kara koso, tanomitai no desu.', 'It is precisely because it is you that I want to ask.'], ['苦労したからこそ、成功の喜びは大きい。', 'くろうしたからこそ、せいこうのよろこびはおおきい。', 'kurou shita kara koso, seikou no yorokobi wa ookii.', 'Precisely because I struggled, the joy of success is great.'], ['好きだからこそ、厳しく言うのだ。', 'すきだからこそ、きびしくいうのだ。', 'suki da kara koso, kibishiku iu no da.', 'It is because I care that I speak harshly.']],
    mistakes: ['からこそ gives a positive, deliberate reason, not an excuse.'],
    exercises: [{ type: 'fill', prompt: '努力した＿、合格できた。', answer: 'からこそ', choices: ['からこそ', 'からには', 'からして'], why: 'Emphasised reason: からこそ.' }] },
  { id: 'kara-shite', unit: 7, title: '〜からして', pattern: '[N] からして', summary: 'judging from; even (starting with)', explanation: 'Two uses: "judging from N" (態度からして) and "even N, to begin with" (名前からして変だ).',
    ex: [['話し方からして、彼は関西の人だろう。', 'はなしかたからして、かれはかんさいのひとだろう。', 'hanashikata kara shite, kare wa kansai no hito darou.', 'Judging from the way he talks, he is probably from Kansai.'], ['この店は名前からして面白い。', 'このみせはなまえからしておもしろい。', 'kono mise wa namae kara shite omoshiroi.', 'This shop is interesting, starting with its name.'], ['服装からして、学生ではなさそうだ。', 'ふくそうからして、がくせいではなさそうだ。', 'fukusou kara shite, gakusei de wa nasasou da.', 'Judging from the clothes, he does not seem to be a student.']],
    mistakes: ['からすると is only "judging from"; からして can also mean "even".'],
    exercises: [{ type: 'fill', prompt: '態度＿、彼は反省していない。', answer: 'からして', choices: ['からして', 'からこそ', 'からには'], why: 'Judging from: からして.' }] },
  { id: 'kara-suru-to', unit: 8, title: '〜からすると・〜からすれば', pattern: '[N] からすると / からすれば / から見ると', summary: 'from the standpoint of; judging from', explanation: 'States the viewpoint or evidence a judgement is based on.',
    ex: [['親からすれば、子供はいつまでも子供だ。', 'おやからすれば、こどもはいつまでもこどもだ。', 'oya kara sureba, kodomo wa itsu made mo kodomo da.', 'From a parent\'s point of view, a child is always a child.'], ['この成績からすると、合格は難しい。', 'このせいせきからすると、ごうかくはむずかしい。', 'kono seiseki kara suru to, goukaku wa muzukashii.', 'Judging from these grades, passing will be difficult.'], ['外国人から見ると、日本の電車は正確だ。', 'がいこくじんからみると、にほんのでんしゃはせいかくだ。', 'gaikokujin kara miru to, nihon no densha wa seikaku da.', 'From a foreigner\'s perspective, Japanese trains are punctual.']],
    mistakes: ['にとって gives a viewpoint for evaluation; からすると also covers evidence.'],
    exercises: [{ type: 'fill', prompt: '専門家＿、この計画には無理がある。', answer: 'からすると', choices: ['からすると', 'からといって', 'からこそ'], why: 'Viewpoint: からすると.' }] },
  { id: 'kara-to-itte', unit: 8, title: '〜からといって', pattern: '[plain] からといって', summary: 'just because … does not mean', explanation: 'Denies that a reason is sufficient. Usually followed by a negative (とは限らない, わけではない).',
    ex: [['日本人だからといって、敬語が使えるとは限らない。', 'にほんじんだからといって、けいごがつかえるとはかぎらない。', 'nihonjin da kara to itte, keigo ga tsukaeru to wa kagiranai.', 'Just because someone is Japanese does not mean they can use honorifics.'], ['安いからといって、たくさん買うのはよくない。', 'やすいからといって、たくさんかうのはよくない。', 'yasui kara to itte, takusan kau no wa yoku nai.', 'Just because it is cheap, buying a lot is not good.'], ['疲れたからといって、休むわけにはいかない。', 'つかれたからといって、やすむわけにはいかない。', 'tsukareta kara to itte, yasumu wake ni wa ikanai.', 'Just because I am tired, I cannot take a rest.']],
    mistakes: ['Needs a negative or restrictive ending.'],
    exercises: [{ type: 'fill', prompt: '有名だ＿、おいしいとは限らない。', answer: 'からといって', choices: ['からといって', 'からすると', 'からこそ'], why: 'Insufficient reason: からといって.' }] },
  { id: 'kara-ni-kakete', unit: 9, title: '〜から〜にかけて', pattern: '[N] から [N] にかけて', summary: 'from … through …', explanation: 'A vague span of time or space from one point through another.',
    ex: [['今夜から明日の朝にかけて、雪が降るでしょう。', 'こんやからあしたのあさにかけて、ゆきがふるでしょう。', 'kon\'ya kara ashita no asa ni kakete, yuki ga furu deshou.', 'From tonight through tomorrow morning, it will probably snow.'], ['関東から東北にかけて、強い風が吹いた。', 'かんとうからとうほくにかけて、つよいかぜがふいた。', 'kantou kara touhoku ni kakete, tsuyoi kaze ga fuita.', 'Strong winds blew from Kanto through Tohoku.'], ['三月から四月にかけて桜が咲く。', 'さんがつからしがつにかけてさくらがさく。', 'sangatsu kara shigatsu ni kakete sakura ga saku.', 'Cherry blossoms bloom from March into April.']],
    mistakes: ['から〜まで has sharp limits; にかけて is approximate.'],
    exercises: [{ type: 'fill', prompt: '夕方から夜＿、雨が強くなる。', answer: 'にかけて', choices: ['にかけて', 'にわたって', 'にしては'], why: 'Approximate span: から〜にかけて.' }] },
  { id: 'kawari-ni', unit: 9, title: '〜かわりに', pattern: '[plain / N の] かわりに', summary: 'instead of; in return for', explanation: 'かわりに after a clause: instead of doing X, do Y; or X in exchange for Y.',
    ex: [['電話するかわりに、メールを送った。', 'でんわするかわりに、メールをおくった。', 'denwa suru kawari ni, meeru o okutta.', 'Instead of phoning, I sent an email.'], ['手伝ってもらうかわりに、昼ご飯をおごるよ。', 'てつだってもらうかわりに、ひるごはんをおごるよ。', 'tetsudatte morau kawari ni, hirugohan o ogoru yo.', 'In return for your help, I will treat you to lunch.'], ['このアパートは駅に近いかわりに、うるさい。', 'このアパートはえきにちかいかわりに、うるさい。', 'kono apaato wa eki ni chikai kawari ni, urusai.', 'This apartment is near the station, but in exchange it is noisy.']],
    mistakes: ['N に代わって is "on behalf of a person"; かわりに is wider.'],
    exercises: [{ type: 'fill', prompt: '車で行く＿、自転車で行くことにした。', answer: 'かわりに', choices: ['かわりに', 'からには', 'くせに'], why: 'Instead of: かわりに.' }] },
  { id: 'kiri', unit: 10, title: '〜きり・〜きりだ', pattern: '[V-た] きり（だ） / [N] きり', summary: 'ever since (no change); only', explanation: 'たきり: something happened and nothing has changed since. Nきり: only (二人きり).',
    ex: [['彼は出かけたきり、戻ってこない。', 'かれはでかけたきり、もどってこない。', 'kare wa dekaketa kiri, modotte konai.', 'He went out and has not come back since.'], ['去年会ったきりで、連絡していない。', 'きょねんあったきりで、れんらくしていない。', 'kyonen atta kiri de, renraku shite inai.', 'I saw him last year and have not been in touch since.'], ['二人きりで話したい。', 'ふたりきりではなしたい。', 'futari kiri de hanashitai.', 'I want to talk just the two of us.']],
    mistakes: ['たきり implies the expected follow-up did not happen.'],
    exercises: [{ type: 'fill', prompt: '友達は本を借りていった＿、返してくれない。', answer: 'きり', choices: ['きり', 'かけ', 'ところ'], why: 'No change since: たきり.' }] },
  { id: 'kuse-ni', unit: 10, title: '〜くせに', pattern: '[plain / N の / な-adj な] くせに', summary: 'even though (critical)', explanation: 'Like のに, but with contempt or blame. Only about other people.',
    ex: [['知っているくせに、教えてくれない。', 'しっているくせに、おしえてくれない。', 'shitte iru kuse ni, oshiete kurenai.', 'Even though he knows, he will not tell me.'], ['子供のくせに、生意気なことを言う。', 'こどものくせに、なまいきなことをいう。', 'kodomo no kuse ni, namaiki na koto o iu.', 'Though just a child, he says cheeky things.'], ['下手なくせに、人の歌を笑う。', 'へたなくせに、ひとのうたをわらう。', 'heta na kuse ni, hito no uta o warau.', 'Though he is bad himself, he laughs at others\' singing.']],
    mistakes: ['Never use くせに about yourself or a superior; it is rude.'],
    exercises: [{ type: 'fill', prompt: 'お金がない＿、高い物ばかり買う。', answer: 'くせに', choices: ['くせに', 'うえに', 'かわりに'], why: 'Critical "although": くせに.' }] },
  { id: 'ge', unit: 11, title: '〜げ', pattern: '[い-adj stem / な-adj] げ', summary: 'looking … (appearance of a feeling)', explanation: 'げ turns a feeling adjective into "looking …": 寂しげ, 楽しげ, 不安げ, 意味ありげ.',
    ex: [['彼女は寂しげに窓の外を見ていた。', 'かのじょはさびしげにまどのそとをみていた。', 'kanojo wa sabishige ni mado no soto o mite ita.', 'She was looking out of the window with a lonely air.'], ['子供たちは楽しげに遊んでいる。', 'こどもたちはたのしげにあそんでいる。', 'kodomotachi wa tanoshige ni asonde iru.', 'The children are playing happily.'], ['彼は不安げな顔で結果を待った。', 'かれはふあんげなかおでけっかをまった。', 'kare wa fuange na kao de kekka o matta.', 'He waited for the results with an anxious face.']],
    mistakes: ['そう (looks) is wider; げ is mostly for emotions, in writing.'],
    exercises: [{ type: 'fill', prompt: '彼は自信あり＿に答えた。', answer: 'げ', choices: ['げ', 'がち', 'っぽい'], why: 'Appearance of a feeling: げ.' }] },
  { id: 'koso', unit: 11, title: '〜こそ', pattern: '[N] こそ / [V-て] こそ', summary: 'precisely; it is X that', explanation: 'こそ singles out the preceding word for emphasis. てこそ: only by doing X does Y hold.',
    ex: [['今度こそ合格したい。', 'こんどこそごうかくしたい。', 'kondo koso goukaku shitai.', 'This time for sure I want to pass.'], ['こちらこそよろしくお願いします。', 'こちらこそよろしくおねがいします。', 'kochira koso yoroshiku onegai shimasu.', 'It is I who should say so; pleased to meet you.'], ['自分で経験してこそ、本当に分かる。', 'じぶんでけいけんしてこそ、ほんとうにわかる。', 'jibun de keiken shite koso, hontou ni wakaru.', 'Only by experiencing it yourself do you truly understand.']],
    mistakes: ['こそ replaces は or が; do not say 今度はこそ.'],
    exercises: [{ type: 'fill', prompt: '苦労して＿、成功の価値が分かる。', answer: 'こそ', choices: ['こそ', 'さえ', 'だけ'], why: 'Only by doing: てこそ.' }] },
  { id: 'koto-ka', unit: 12, title: '〜ことか', pattern: 'どんなに / 何度 / 何回 … [plain] ことか', summary: 'how …! (exclamation)', explanation: 'With a question word, ことか makes a strong exclamation: どんなに嬉しいことか.',
    ex: [['合格したと聞いて、どんなに嬉しかったことか。', 'ごうかくしたときいて、どんなにうれしかったことか。', 'goukaku shita to kiite, donna ni ureshikatta koto ka.', 'How happy I was to hear that I passed!'], ['何度注意したことか。', 'なんどちゅういしたことか。', 'nando chuui shita koto ka.', 'How many times have I warned you!'], ['一人で育てるのが、どれほど大変だったことか。', 'ひとりでそだてるのが、どれほどたいへんだったことか。', 'hitori de sodateru no ga, dore hodo taihen datta koto ka.', 'How hard it was to raise them alone!']],
    mistakes: ['Needs a question word (どんなに, 何度, どれほど).'],
    exercises: [{ type: 'fill', prompt: 'この日をどれほど待っていた＿。', answer: 'ことか', choices: ['ことか', 'ものか', 'ことだ'], why: 'Exclamation: ことか.' }] },
  { id: 'koto-kara', unit: 12, title: '〜ことから', pattern: '[plain] ことから', summary: 'from the fact that; because', explanation: 'States the fact a conclusion or name derives from.',
    ex: [['窓が割れていることから、泥棒が入ったと分かった。', 'まどがわれていることから、どろぼうがはいったとわかった。', 'mado ga warete iru koto kara, dorobou ga haitta to wakatta.', 'From the fact that the window was broken, we knew a thief had entered.'], ['この町は桜が多いことから、桜町と呼ばれている。', 'このまちはさくらがおおいことから、さくらまちとよばれている。', 'kono machi wa sakura ga ooi koto kara, sakuramachi to yobarete iru.', 'Because it has many cherry trees, this town is called Sakuramachi.'], ['顔が似ていることから、兄弟だと思われた。', 'かおがにていることから、きょうだいだとおもわれた。', 'kao ga nite iru koto kara, kyoudai da to omowareta.', 'Because their faces were alike, they were taken for brothers.']],
    mistakes: ['Reason for a judgement or a name, not for an order or request.'],
    exercises: [{ type: 'fill', prompt: '靴が濡れている＿、外は雨だと分かる。', answer: 'ことから', choices: ['ことから', 'ことなく', 'ことだから'], why: 'Fact leading to a conclusion: ことから.' }] },
  { id: 'koto-da', unit: 13, title: '〜ことだ', pattern: '[V-dictionary / V-ない] ことだ', summary: 'you should (advice)', explanation: 'A firm piece of advice from a superior or experienced person.',
    ex: [['上手になりたければ、毎日練習することだ。', 'じょうずになりたければ、まいにちれんしゅうすることだ。', 'jouzu ni naritakereba, mainichi renshuu suru koto da.', 'If you want to get good, practise every day.'], ['風邪のときは無理をしないことだ。', 'かぜのときはむりをしないことだ。', 'kaze no toki wa muri o shinai koto da.', 'When you have a cold, you should not overdo it.'], ['迷ったら、先生に相談することだ。', 'まよったら、せんせいにそうだんすることだ。', 'mayottara, sensei ni soudan suru koto da.', 'If you are unsure, consult your teacher.']],
    mistakes: ['Not for yourself; it is advice to others.'],
    exercises: [{ type: 'fill', prompt: '痩せたいなら、甘い物を食べない＿。', answer: 'ことだ', choices: ['ことだ', 'ものだ', 'ことか'], why: 'Advice: ことだ.' }] },
  { id: 'koto-da-kara', unit: 13, title: '〜ことだから', pattern: '[N] のことだから', summary: 'knowing (someone), surely', explanation: 'A guess based on what is known about a person: 彼のことだから, きっと…',
    ex: [['真面目な彼のことだから、遅刻はしないだろう。', 'まじめなかれのことだから、ちこくはしないだろう。', 'majime na kare no koto da kara, chikoku wa shinai darou.', 'Knowing how serious he is, he will not be late.'], ['あなたのことだから、きっと成功するよ。', 'あなたのことだから、きっとせいこうするよ。', 'anata no koto da kara, kitto seikou suru yo.', 'Knowing you, you will surely succeed.'], ['忙しい母のことだから、まだ気づいていないだろう。', 'いそがしいははのことだから、まだきづいていないだろう。', 'isogashii haha no koto da kara, mada kizuite inai darou.', 'Knowing how busy my mother is, she probably has not noticed yet.']],
    mistakes: ['Almost always about a person, with a known trait.'],
    exercises: [{ type: 'fill', prompt: '優しい田中さん＿、手伝ってくれるはずだ。', answer: 'のことだから', choices: ['のことだから', 'のことなく', 'のことには'], why: 'Guess from character: のことだから.' }] },
  { id: 'koto-naku', unit: 14, title: '〜ことなく', pattern: '[V-dictionary] ことなく', summary: 'without ever doing (formal)', explanation: 'A written equivalent of ないで, often for continuous effort: 休むことなく働いた.',
    ex: [['彼は一度も休むことなく働き続けた。', 'かれはいちどもやすむことなくはたらきつづけた。', 'kare wa ichido mo yasumu koto naku hatarakitsuzuketa.', 'He kept working without once resting.'], ['諦めることなく、最後まで戦った。', 'あきらめることなく、さいごまでたたかった。', 'akirameru koto naku, saigo made tatakatta.', 'Without giving up, they fought to the end.'], ['誰にも知られることなく、彼は町を去った。', 'だれにもしられることなく、かれはまちをさった。', 'dare ni mo shirareru koto naku, kare wa machi o satta.', 'Without anyone knowing, he left the town.']],
    mistakes: ['Formal; use ないで in conversation.'],
    exercises: [{ type: 'fill', prompt: '雨にも負ける＿、走り続けた。', answer: 'ことなく', choices: ['ことなく', 'ことから', 'ことに'], why: 'Without doing: ことなく.' }] },
  { id: 'koto-ni', unit: 14, title: '〜ことに（は）', pattern: '[感情 adj / V-た] ことに', summary: 'to my (surprise / regret)', explanation: 'An emotion word + ことに fronts the speaker\'s feeling about what follows: 驚いたことに, 残念なことに.',
    ex: [['驚いたことに、彼は全問正解だった。', 'おどろいたことに、かれはぜんもんせいかいだった。', 'odoroita koto ni, kare wa zenmon seikai datta.', 'To my surprise, he answered every question correctly.'], ['残念なことに、試合は中止になった。', 'ざんねんなことに、しあいはちゅうしになった。', 'zannen na koto ni, shiai wa chuushi ni natta.', 'Regrettably, the match was cancelled.'], ['嬉しいことに、昔の友人から手紙が来た。', 'うれしいことに、むかしのゆうじんからてがみがきた。', 'ureshii koto ni, mukashi no yuujin kara tegami ga kita.', 'Happily, a letter came from an old friend.']],
    mistakes: ['Only with emotion words.'],
    exercises: [{ type: 'fill', prompt: '困った＿、財布を忘れてしまった。', answer: 'ことに', choices: ['ことに', 'ことで', 'ことか'], why: 'Speaker\'s feeling: ことに.' }] },
  { id: 'koto-ni-natte-iru', unit: 15, title: '〜ことになっている', pattern: '[V-dictionary / V-ない] ことになっている', summary: 'it is the rule / arrangement that', explanation: 'A rule, schedule or custom that has been decided.',
    ex: [['この寮では十時までに帰ることになっている。', 'このりょうではじゅうじまでにかえることになっている。', 'kono ryou de wa juuji made ni kaeru koto ni natte iru.', 'In this dormitory, the rule is to be back by ten.'], ['来週、部長と会うことになっている。', 'らいしゅう、ぶちょうとあうことになっている。', 'raishuu, buchou to au koto ni natte iru.', 'It is arranged that I meet the manager next week.'], ['教室では日本語しか使わないことになっている。', 'きょうしつではにほんごしかつかわないことになっている。', 'kyoushitsu de wa nihongo shika tsukawanai koto ni natte iru.', 'The rule is that only Japanese is used in the classroom.']],
    mistakes: ['ことにしている is your own habit; ことになっている is an external rule.'],
    exercises: [{ type: 'fill', prompt: '社員は毎朝九時に出社する＿。', answer: 'ことになっている', choices: ['ことになっている', 'ことにしている', 'ことはない'], why: 'External rule: ことになっている.' }] },
  { id: 'koto-wa-nai', unit: 15, title: '〜ことはない', pattern: '[V-dictionary] ことはない', summary: 'there is no need to', explanation: 'Reassures that something is unnecessary: 心配することはない.',
    ex: [['そんなに心配することはない。', 'そんなにしんぱいすることはない。', 'sonna ni shinpai suru koto wa nai.', 'There is no need to worry so much.'], ['わざわざ行くことはないよ。電話で済む。', 'わざわざいくことはないよ。でんわですむ。', 'wazawaza iku koto wa nai yo. denwa de sumu.', 'No need to go all the way; a phone call will do.'], ['謝ることはありません。あなたは悪くない。', 'あやまることはありません。あなたはわるくない。', 'ayamaru koto wa arimasen. anata wa waruku nai.', 'There is no need to apologise; you are not at fault.']],
    mistakes: ['たことがない (never have) is a different pattern.'],
    exercises: [{ type: 'fill', prompt: '小さなミスだから、気にする＿。', answer: 'ことはない', choices: ['ことはない', 'ことがない', 'ことだ'], why: 'No need: ことはない.' }] },
  { id: 'sai-ni', unit: 16, title: '〜際（に）', pattern: '[V-dictionary / V-た / N の] 際（に）', summary: 'on the occasion of (formal とき)', explanation: 'A formal "when", used in notices and business.',
    ex: [['お帰りの際は、忘れ物にご注意ください。', 'おかえりのさいは、わすれものにごちゅういください。', 'okaeri no sai wa, wasuremono ni gochuui kudasai.', 'When leaving, please take care not to forget anything.'], ['申し込みの際に、写真が必要です。', 'もうしこみのさいに、しゃしんがひつようです。', 'moushikomi no sai ni, shashin ga hitsuyou desu.', 'A photo is required when applying.'], ['京都を訪れた際、古い寺を見学した。', 'きょうとをおとずれたさい、ふるいてらをけんがくした。', 'kyouto o otozureta sai, furui tera o kengaku shita.', 'When I visited Kyoto, I toured an old temple.']],
    mistakes: ['Formal; not for everyday actions like 寝る際.'],
    exercises: [{ type: 'fill', prompt: 'ご利用の＿は、カードをお持ちください。', answer: '際', choices: ['際', '最中', 'うち'], why: 'Formal "when": 際.' }] },
  { id: 'saichuu-ni', unit: 16, title: '〜最中に', pattern: '[V-ている / N の] 最中に', summary: 'right in the middle of', explanation: 'Something interrupts an action in progress.',
    ex: [['会議の最中に、電話が鳴った。', 'かいぎのさいちゅうに、でんわがなった。', 'kaigi no saichuu ni, denwa ga natta.', 'Right in the middle of the meeting, the phone rang.'], ['食事をしている最中に、客が来た。', 'しょくじをしているさいちゅうに、きゃくがきた。', 'shokuji o shite iru saichuu ni, kyaku ga kita.', 'In the middle of the meal, a visitor came.'], ['今、調べている最中です。', 'いま、しらべているさいちゅうです。', 'ima, shirabete iru saichuu desu.', 'I am right in the middle of looking into it now.']],
    mistakes: ['Not for states: 寝ている最中 is odd; use 間に.'],
    exercises: [{ type: 'fill', prompt: 'シャワーを浴びている＿、停電になった。', answer: '最中に', choices: ['最中に', '際に', 'うちに'], why: 'Interrupted action: 最中に.' }] },
  { id: 'sae', unit: 17, title: '〜さえ・〜さえ〜ば', pattern: '[N] さえ / [V-stem] さえすれば / [N] さえ〜ば', summary: 'even; if only', explanation: 'さえ: even (an extreme example). さえ〜ば: the one condition that suffices.',
    ex: [['忙しくて、昼ご飯を食べる時間さえない。', 'いそがしくて、ひるごはんをたべるじかんさえない。', 'isogashikute, hirugohan o taberu jikan sae nai.', 'I am so busy that I do not even have time to eat lunch.'], ['薬を飲みさえすれば、治ります。', 'くすりをのみさえすれば、なおります。', 'kusuri o nomi sae sureba, naorimasu.', 'If only you take the medicine, you will get better.'], ['お金さえあれば、何でもできるわけではない。', 'おかねさえあれば、なんでもできるわけではない。', 'okane sae areba, nandemo dekiru wake de wa nai.', 'It is not that you can do anything if only you have money.']],
    mistakes: ['でさえ or でも can replace さえ for "even".'],
    exercises: [{ type: 'fill', prompt: '時間＿あれば、もっと練習できるのに。', answer: 'さえ', choices: ['さえ', 'こそ', 'ほど'], why: 'Sufficient condition: さえ〜ば.' }] },
  { id: 'zaru-o-enai', unit: 17, title: '〜ざるを得ない', pattern: '[V-ない stem] ざるを得ない (する → せざるを得ない)', summary: 'have no choice but to', explanation: 'Formal: circumstances force the action.',
    ex: [['台風で、旅行は中止せざるを得なかった。', 'たいふうで、りょこうはちゅうしせざるをえなかった。', 'taifuu de, ryokou wa chuushi sezaru o enakatta.', 'Because of the typhoon, we had no choice but to cancel the trip.'], ['上司の命令なら、従わざるを得ない。', 'じょうしのめいれいなら、したがわざるをえない。', 'joushi no meirei nara, shitagawazaru o enai.', 'If it is the boss\'s order, I have no choice but to obey.'], ['証拠があるので、認めざるを得ない。', 'しょうこがあるので、みとめざるをえない。', 'shouko ga aru node, mitomezaru o enai.', 'Since there is evidence, I have to admit it.']],
    mistakes: ['する becomes せざる, not しざる.'],
    exercises: [{ type: 'fill', prompt: '値段が上がったので、計画を変え＿。', answer: 'ざるを得ない', choices: ['ざるを得ない', 'ずにはいられない', 'ないことはない'], why: 'Forced: ざるを得ない.' }] },
  { id: 'shidai', unit: 18, title: '〜次第で・〜次第だ', pattern: '[N] 次第で / 次第だ', summary: 'depending on', explanation: 'The result depends entirely on N: 天気次第で, 努力次第だ. (V-stem + 次第 "as soon as" was N3.)',
    ex: [['成功するかどうかは、努力次第だ。', 'せいこうするかどうかは、どりょくしだいだ。', 'seikou suru ka dou ka wa, doryoku shidai da.', 'Whether you succeed depends on your effort.'], ['天気次第で、予定を変えます。', 'てんきしだいで、よていをかえます。', 'tenki shidai de, yotei o kaemasu.', 'Depending on the weather, we will change the plan.'], ['考え方次第で、人生は変わる。', 'かんがえかたしだいで、じんせいはかわる。', 'kangaekata shidai de, jinsei wa kawaru.', 'Depending on how you think, life changes.']],
    mistakes: ['Vます + 次第 is "as soon as"; N + 次第 is "depending on".'],
    exercises: [{ type: 'fill', prompt: '値段は品質＿です。', answer: '次第', choices: ['次第', '向き', 'だらけ'], why: 'Depending on: N次第.' }] },
  { id: 'jou', unit: 18, title: '〜上（は）・〜上の', pattern: '[N] 上 / 上は / 上の', summary: 'from the point of view of; -wise', explanation: '法律上, 教育上, 健康上, 表面上: "in terms of N".',
    ex: [['法律上、それは許されない。', 'ほうりつじょう、それはゆるされない。', 'houritsujou, sore wa yurusarenai.', 'Legally, that is not permitted.'], ['健康上の理由で、仕事を辞めた。', 'けんこうじょうのりゆうで、しごとをやめた。', 'kenkoujou no riyuu de, shigoto o yameta.', 'For health reasons, I quit my job.'], ['表面上は仲が良さそうに見える。', 'ひょうめんじょうはなかがよさそうにみえる。', 'hyoumenjou wa naka ga yosasou ni mieru.', 'On the surface, they seem to get along.']],
    mistakes: ['Read じょう, attached directly to a Sino-Japanese noun.'],
    exercises: [{ type: 'fill', prompt: '安全＿の問題があるので、工事を止めた。', answer: '上', choices: ['上', '中', '際'], why: 'In terms of: N上.' }] },
  { id: 'zu-ni-wa-irarenai', unit: 19, title: '〜ずにはいられない・〜ないではいられない', pattern: '[V-ない stem] ずにはいられない / [V-ない] ではいられない', summary: 'cannot help but', explanation: 'The speaker cannot suppress an urge or feeling. する → せずにはいられない.',
    ex: [['あの映画を見ると、泣かずにはいられない。', 'あのえいがをみると、なかずにはいられない。', 'ano eiga o miru to, nakazu ni wa irarenai.', 'When I watch that film, I cannot help crying.'], ['おかしくて、笑わないではいられなかった。', 'おかしくて、わらわないではいられなかった。', 'okashikute, warawanai de wa irarenakatta.', 'It was so funny that I could not help laughing.'], ['彼の話を聞いて、同情せずにはいられない。', 'かれのはなしをきいて、どうじょうせずにはいられない。', 'kare no hanashi o kiite, doujou sezu ni wa irarenai.', 'Hearing his story, I cannot help feeling sympathy.']],
    mistakes: ['About feelings and urges; ざるを得ない is about circumstances.'],
    exercises: [{ type: 'fill', prompt: 'いい知らせを聞いて、喜ば＿。', answer: 'ずにはいられない', choices: ['ずにはいられない', 'ざるを得ない', 'ないわけにはいかない'], why: 'Cannot suppress a feeling: ずにはいられない.' }] },
  { id: 'sei-ka', unit: 19, title: '〜せいか', pattern: '[plain / N の / な-adj な] せいか', summary: 'perhaps because (of a bad cause)', explanation: 'せいか gives an uncertain reason for a bad result.',
    ex: [['疲れているせいか、頭が痛い。', 'つかれているせいか、あたまがいたい。', 'tsukarete iru sei ka, atama ga itai.', 'Perhaps because I am tired, I have a headache.'], ['年のせいか、最近物忘れが多い。', 'としのせいか、さいきんものわすれがおおい。', 'toshi no sei ka, saikin monowasure ga ooi.', 'Perhaps because of age, I forget things a lot lately.'], ['雨のせいか、客が少ない。', 'あめのせいか、きゃくがすくない。', 'ame no sei ka, kyaku ga sukunai.', 'Maybe because of the rain, there are few customers.']],
    mistakes: ['おかげか would be the positive version.'],
    exercises: [{ type: 'fill', prompt: '寝不足の＿、集中できない。', answer: 'せいか', choices: ['せいか', 'おかげか', 'ためか'], why: 'Uncertain bad cause: せいか.' }] },
  { id: 'dake-atte', unit: 20, title: '〜だけあって・〜だけに', pattern: '[plain / N] だけあって / だけに', summary: 'as expected of; precisely because', explanation: 'だけあって: the result fits the reason (praise). だけに: because of that very fact, the effect is greater.',
    ex: [['高いだけあって、この店の料理はおいしい。', 'たかいだけあって、このみせのりょうりはおいしい。', 'takai dake atte, kono mise no ryouri wa oishii.', 'As you would expect from the price, this restaurant\'s food is delicious.'], ['さすがプロだけあって、仕事が速い。', 'さすがプロだけあって、しごとがはやい。', 'sasuga puro dake atte, shigoto ga hayai.', 'As expected of a professional, he works fast.'], ['期待していただけに、失敗が悔しい。', 'きたいしていただけに、しっぱいがくやしい。', 'kitai shite ita dake ni, shippai ga kuyashii.', 'Precisely because I had expected so much, the failure is frustrating.']],
    mistakes: ['だけあって is mostly for positive outcomes.'],
    exercises: [{ type: 'fill', prompt: '十年住んでいた＿、この町のことをよく知っている。', answer: 'だけあって', choices: ['だけあって', 'だけで', 'だけは'], why: 'Fitting result: だけあって.' }] },
  { id: 'tatoe-temo', unit: 20, title: 'たとえ〜ても', pattern: 'たとえ [V-て] も / [い-adj くて] も / [N で] も', summary: 'even if', explanation: 'たとえ strengthens ても: whatever the hypothetical case, the result holds.',
    ex: [['たとえ雨が降っても、試合は行われる。', 'たとえあめがふっても、しあいはおこなわれる。', 'tatoe ame ga futte mo, shiai wa okonawareru.', 'Even if it rains, the match will be held.'], ['たとえ難しくても、諦めない。', 'たとえむずかしくても、あきらめない。', 'tatoe muzukashikute mo, akiramenai.', 'Even if it is hard, I will not give up.'], ['たとえ冗談でも、そんなことを言ってはいけない。', 'たとえじょうだんでも、そんなことをいってはいけない。', 'tatoe joudan de mo, sonna koto o itte wa ikenai.', 'Even as a joke, you must not say such a thing.']],
    mistakes: ['たとえ needs ても; たとえ〜なら is wrong.'],
    exercises: [{ type: 'fill', prompt: '＿反対されても、留学するつもりだ。', answer: 'たとえ', choices: ['たとえ', 'いくら', 'まるで'], why: 'Even if: たとえ〜ても.' }] },
  { id: 'ta-tokoro', unit: 21, title: '〜たところ', pattern: '[V-た] ところ', summary: 'when I did X, (I found)', explanation: 'An action and its unexpected or newly discovered result.',
    ex: [['先生に相談したところ、いい方法を教えてくれた。', 'せんせいにそうだんしたところ、いいほうほうをおしえてくれた。', 'sensei ni soudan shita tokoro, ii houhou o oshiete kureta.', 'When I consulted the teacher, she told me a good method.'], ['店に電話したところ、もう売り切れだった。', 'みせにでんわしたところ、もううりきれだった。', 'mise ni denwa shita tokoro, mou urikire datta.', 'When I called the shop, it was already sold out.'], ['調べたところ、原因は電池だった。', 'しらべたところ、げんいんはでんちだった。', 'shirabeta tokoro, gen\'in wa denchi datta.', 'When I checked, the cause was the battery.']],
    mistakes: ['The result is a discovery, not the speaker\'s next deliberate action.'],
    exercises: [{ type: 'fill', prompt: '薬を飲んだ＿、すぐに楽になった。', answer: 'ところ', choices: ['ところ', 'とたん', 'ついでに'], why: 'Result found: たところ.' }] },
  { id: 'ta-totan', unit: 21, title: '〜たとたん（に）', pattern: '[V-た] とたん（に）', summary: 'the moment; just as', explanation: 'Something happens the instant another action finishes, often unexpectedly.',
    ex: [['ドアを開けたとたん、犬が飛び出してきた。', 'ドアをあけたとたん、いぬがとびだしてきた。', 'doa o aketa totan, inu ga tobidashite kita.', 'The moment I opened the door, the dog rushed out.'], ['立ち上がったとたんに、めまいがした。', 'たちあがったとたんに、めまいがした。', 'tachiagatta totan ni, memai ga shita.', 'Just as I stood up, I felt dizzy.'], ['彼の顔を見たとたん、涙が出た。', 'かれのかおをみたとたん、なみだがでた。', 'kare no kao o mita totan, namida ga deta.', 'The moment I saw his face, tears came.']],
    mistakes: ['Not for intentional follow-up actions (×とたんに電話した).'],
    exercises: [{ type: 'fill', prompt: '窓を開けた＿、冷たい風が入ってきた。', answer: 'とたん', choices: ['とたん', 'ところ', 'うちに'], why: 'Instant follow-on: たとたん.' }] },
  { id: 'darake', unit: 22, title: '〜だらけ', pattern: '[N] だらけ', summary: 'full of; covered in (bad)', explanation: 'だらけ: covered or full of something undesirable: 泥だらけ, 間違いだらけ.',
    ex: [['子供は泥だらけになって帰ってきた。', 'こどもはどろだらけになってかえってきた。', 'kodomo wa doro darake ni natte kaette kita.', 'The child came home covered in mud.'], ['この作文は間違いだらけだ。', 'このさくぶんはまちがいだらけだ。', 'kono sakubun wa machigai darake da.', 'This essay is full of mistakes.'], ['部屋がごみだらけで、足の踏み場もない。', 'へやがごみだらけで、あしのふみばもない。', 'heya ga gomi darake de, ashi no fumiba mo nai.', 'The room is so full of rubbish there is nowhere to step.']],
    mistakes: ['Negative; for a pleasant fullness use いっぱい.'],
    exercises: [{ type: 'fill', prompt: '机の上はほこり＿だった。', answer: 'だらけ', choices: ['だらけ', 'ぎみ', 'っぽい'], why: 'Covered in something bad: だらけ.' }] },
  { id: 'tsuide-ni', unit: 22, title: '〜ついでに', pattern: '[V-dictionary / V-た / N の] ついでに', summary: 'while you are at it', explanation: 'Doing a secondary thing on the occasion of a main one.',
    ex: [['買い物のついでに、郵便局に寄った。', 'かいもののついでに、ゆうびんきょくによった。', 'kaimono no tsuide ni, yuubinkyoku ni yotta.', 'While out shopping, I dropped by the post office.'], ['出かけるついでに、ごみを出してくれる？', 'でかけるついでに、ごみをだしてくれる？', 'dekakeru tsuide ni, gomi o dashite kureru?', 'Since you are going out, could you take out the rubbish?'], ['実家に帰ったついでに、昔の友達に会った。', 'じっかにかえったついでに、むかしのともだちにあった。', 'jikka ni kaetta tsuide ni, mukashi no tomodachi ni atta.', 'While visiting my parents\' home, I met old friends.']],
    mistakes: ['The main action comes first; the extra one follows ついでに.'],
    exercises: [{ type: 'fill', prompt: '散歩の＿、パンを買ってきた。', answer: 'ついでに', choices: ['ついでに', 'とたんに', 'かわりに'], why: 'Secondary action: ついでに.' }] },
  { id: 'kke', unit: 23, title: '〜っけ', pattern: '[plain past / N だった] っけ', summary: 'was it …? (recalling)', explanation: 'A casual tag for trying to remember: 何時だったっけ. Follows past forms.',
    ex: [['会議は何時からだったっけ。', 'かいぎはなんじからだったっけ。', 'kaigi wa nanji kara datta kke.', 'What time was the meeting from, again?'], ['あの人の名前、何だっけ。', 'あのひとのなまえ、なんだっけ。', 'ano hito no namae, nan da kke.', 'What was that person\'s name again?'], ['君はコーヒーが好きだったっけ。', 'きみはコーヒーがすきだったっけ。', 'kimi wa koohii ga suki datta kke.', 'You liked coffee, didn\'t you?']],
    mistakes: ['Casual speech only.'],
    exercises: [{ type: 'fill', prompt: '明日の約束は三時だった＿。', answer: 'っけ', choices: ['っけ', 'っこ', 'かな'], why: 'Recalling: っけ.' }] },
  { id: 'kkonai', unit: 23, title: '〜っこない', pattern: '[V-stem] っこない', summary: 'there is no way (casual)', explanation: 'A casual, emphatic denial of possibility.',
    ex: [['そんな難しい問題、解けっこない。', 'そんなむずかしいもんだい、とけっこない。', 'sonna muzukashii mondai, tokekkonai.', 'There is no way I can solve such a hard problem.'], ['一日で覚えられっこないよ。', 'いちにちでおぼえられっこないよ。', 'ichinichi de oboerarekkonai yo.', 'There is no way to memorise it in one day.'], ['彼が来るなんて、ありっこない。', 'かれがくるなんて、ありっこない。', 'kare ga kuru nante, arikkonai.', 'There is no chance he will come.']],
    mistakes: ['Casual; the formal equivalent is はずがない.'],
    exercises: [{ type: 'fill', prompt: 'こんな雨の中、試合はでき＿。', answer: 'っこない', choices: ['っこない', 'かねない', 'きれない'], why: 'Casual impossibility: っこない.' }] },
  { id: 'tsutsu', unit: 24, title: '〜つつ・〜つつある', pattern: '[V-stem] つつ / つつある', summary: 'while; although / in the process of', explanation: 'つつ (written) = ながら, often "although" (知りつつ). つつある: a change in progress.',
    ex: [['悪いと知りつつ、嘘をついた。', 'わるいとしりつつ、うそをついた。', 'warui to shiritsutsu, uso o tsuita.', 'Knowing it was wrong, I lied.'], ['景気は回復しつつある。', 'けいきはかいふくしつつある。', 'keiki wa kaifuku shitsutsu aru.', 'The economy is recovering.'], ['景色を眺めつつ、コーヒーを飲んだ。', 'けしきをながめつつ、コーヒーをのんだ。', 'keshiki o nagametsutsu, koohii o nonda.', 'I drank coffee while gazing at the scenery.']],
    mistakes: ['つつある is for gradual change, not for ongoing simple actions.'],
    exercises: [{ type: 'fill', prompt: '町の人口は減り＿ある。', answer: 'つつ', choices: ['つつ', 'ながら', 'がち'], why: 'Change in progress: つつある.' }] },
  { id: 'te-kara-de-nai-to', unit: 24, title: '〜てからでないと', pattern: '[V-て] からでないと / からでなければ', summary: 'unless you first', explanation: 'The second thing cannot happen until the first is done. Followed by a negative.',
    ex: [['許可をもらってからでないと、入れません。', 'きょかをもらってからでないと、はいれません。', 'kyoka o moratte kara de nai to, hairemasen.', 'You cannot enter unless you first get permission.'], ['試してみてからでないと、分からない。', 'ためしてみてからでないと、わからない。', 'tameshite mite kara de nai to, wakaranai.', 'I will not know until I have tried it.'], ['準備が終わってからでなければ、始められない。', 'じゅんびがおわってからでなければ、はじめられない。', 'junbi ga owatte kara de nakereba, hajimerarenai.', 'We cannot start until the preparations are finished.']],
    mistakes: ['Must end in a negative or impossibility.'],
    exercises: [{ type: 'fill', prompt: '会員になって＿、この施設は使えません。', answer: 'からでないと', choices: ['からでないと', 'からには', 'からこそ'], why: 'Precondition: てからでないと.' }] },
  { id: 'te-tamaranai', unit: 25, title: '〜てたまらない', pattern: '[V-て / い-adj くて / な-adj で] たまらない', summary: 'unbearably; extremely', explanation: 'A feeling or sensation is too strong to bear: 暑くてたまらない, 会いたくてたまらない.',
    ex: [['暑くてたまらない。', 'あつくてたまらない。', 'atsukute tamaranai.', 'It is unbearably hot.'], ['国の家族に会いたくてたまらない。', 'くにのかぞくにあいたくてたまらない。', 'kuni no kazoku ni aitakute tamaranai.', 'I am dying to see my family back home.'], ['結果が気になってたまらない。', 'けっかがきになってたまらない。', 'kekka ga ki ni natte tamaranai.', 'I cannot stop worrying about the results.']],
    mistakes: ['Only with the speaker\'s own feelings and sensations.'],
    exercises: [{ type: 'fill', prompt: '朝から何も食べていないので、お腹が空いて＿。', answer: 'たまらない', choices: ['たまらない', 'かまわない', 'しょうがある'], why: 'Unbearable sensation: てたまらない.' }] },
  { id: 'te-naranai', unit: 25, title: '〜てならない', pattern: '[V-て / い-adj くて / な-adj で] ならない', summary: 'cannot help feeling', explanation: 'Like てたまらない but for spontaneous feelings and thoughts: 気がしてならない, 残念でならない.',
    ex: [['合格できて、嬉しくてならない。', 'ごうかくできて、うれしくてならない。', 'goukaku dekite, ureshikute naranai.', 'Having passed, I am overjoyed.'], ['何か忘れている気がしてならない。', 'なにかわすれているきがしてならない。', 'nanika wasurete iru ki ga shite naranai.', 'I cannot shake the feeling that I have forgotten something.'], ['試合に負けたことが残念でならない。', 'しあいにまけたことがざんねんでならない。', 'shiai ni maketa koto ga zannen de naranai.', 'I am terribly sorry that we lost the match.']],
    mistakes: ['てならない suits feelings and 気がする; てたまらない suits sensations too.'],
    exercises: [{ type: 'fill', prompt: '将来のことが心配で＿。', answer: 'ならない', choices: ['ならない', 'しかたがある', 'かまわない'], why: 'Spontaneous feeling: てならない.' }] },
  { id: 'to-iu-to', unit: 26, title: '〜というと・〜といえば・〜といったら', pattern: '[N] というと / といえば / といったら', summary: 'speaking of; when it comes to', explanation: 'Picks up a topic just mentioned, or expresses an extreme (といったら).',
    ex: [['京都といえば、やはり寺でしょう。', 'きょうとといえば、やはりてらでしょう。', 'kyouto to ieba, yahari tera deshou.', 'Speaking of Kyoto, it has to be the temples.'], ['田中さんというと、あの背の高い人ですか。', 'たなかさんというと、あのせのたかいひとですか。', 'tanaka san to iu to, ano se no takai hito desu ka.', 'Tanaka, you say? Is that the tall person?'], ['あの時の恥ずかしさといったら、言葉にできない。', 'あのときのはずかしさといったら、ことばにできない。', 'ano toki no hazukashisa to ittara, kotoba ni dekinai.', 'The embarrassment of that moment was beyond words.']],
    mistakes: ['といったら often ends with an exclamation of degree.'],
    exercises: [{ type: 'fill', prompt: '日本の夏＿、花火と祭りだ。', answer: 'といえば', choices: ['といえば', 'といっても', 'というより'], why: 'Topic association: といえば.' }] },
  { id: 'to-iu-mono-da', unit: 26, title: '〜というものだ・〜というものではない', pattern: '[plain / N] というものだ / というものではない', summary: 'that is what X is; it is not the case that', explanation: 'というものだ states a general truth with conviction; というものではない denies a common assumption.',
    ex: [['人を助けるのが友達というものだ。', 'ひとをたすけるのがともだちというものだ。', 'hito o tasukeru no ga tomodachi to iu mono da.', 'Helping someone is what a friend is.'], ['お金があれば幸せになれるというものではない。', 'おかねがあればしあわせになれるというものではない。', 'okane ga areba shiawase ni nareru to iu mono de wa nai.', 'It is not the case that having money makes you happy.'], ['安ければいいというものではない。', 'やすければいいというものではない。', 'yasukereba ii to iu mono de wa nai.', 'It is not that cheaper is simply better.']],
    mistakes: ['Used for general statements, not personal reports.'],
    exercises: [{ type: 'fill', prompt: '練習すれば必ず上手になる＿。', answer: 'というものではない', choices: ['というものではない', 'というものか', 'ということだ'], why: 'Denying an assumption: というものではない.' }] },
  { id: 'to-iu-yori', unit: 27, title: '〜というより', pattern: '[plain / N] というより', summary: 'rather than; more … than', explanation: 'Corrects a description: not so much X as Y. Often with むしろ.',
    ex: [['彼は歌手というより、俳優だ。', 'かれはかしゅというより、はいゆうだ。', 'kare wa kashu to iu yori, haiyuu da.', 'He is more an actor than a singer.'], ['今日は涼しいというより、寒い。', 'きょうはすずしいというより、さむい。', 'kyou wa suzushii to iu yori, samui.', 'Today is cold rather than cool.'], ['それは注意というより、むしろ脅しだ。', 'それはちゅういというより、むしろおどしだ。', 'sore wa chuui to iu yori, mushiro odoshi da.', 'That is less a warning than a threat.']],
    mistakes: ['Not for comparing two different things; it corrects a label.'],
    exercises: [{ type: 'fill', prompt: 'この部屋は広い＿、何もないだけだ。', answer: 'というより', choices: ['というより', 'といっても', 'というと'], why: 'Correcting a description: というより.' }] },
  { id: 'to-itte-mo', unit: 27, title: '〜といっても', pattern: '[plain / N] といっても', summary: 'although I say; that said', explanation: 'Qualifies a statement so the listener does not overestimate it.',
    ex: [['日本語ができるといっても、簡単な会話だけです。', 'にほんごができるといっても、かんたんなかいわだけです。', 'nihongo ga dekiru to itte mo, kantan na kaiwa dake desu.', 'I can speak Japanese, but only simple conversation.'], ['旅行といっても、隣の町に行くだけだ。', 'りょこうといっても、となりのまちにいくだけだ。', 'ryokou to itte mo, tonari no machi ni iku dake da.', 'A trip, but only to the next town.'], ['忙しいといっても、休む時間はある。', 'いそがしいといっても、やすむじかんはある。', 'isogashii to itte mo, yasumu jikan wa aru.', 'Busy as I am, I still have time to rest.']],
    mistakes: ['What follows lowers the expectation.'],
    exercises: [{ type: 'fill', prompt: '料理ができる＿、卵焼きぐらいだ。', answer: 'といっても', choices: ['といっても', 'というより', 'といえば'], why: 'Qualifying: といっても.' }] },
  { id: 'dokoro-ka', unit: 28, title: '〜どころか', pattern: '[plain / N] どころか', summary: 'far from; let alone', explanation: 'The reality is the opposite of, or far beyond, what was expected.',
    ex: [['雨はやむどころか、ますます強くなった。', 'あめはやむどころか、ますますつよくなった。', 'ame wa yamu dokoro ka, masumasu tsuyoku natta.', 'Far from stopping, the rain got even heavier.'], ['漢字どころか、ひらがなも読めない。', 'かんじどころか、ひらがなもよめない。', 'kanji dokoro ka, hiragana mo yomenai.', 'He cannot even read hiragana, let alone kanji.'], ['褒められるどころか、叱られてしまった。', 'ほめられるどころか、しかられてしまった。', 'homerareru dokoro ka, shikararete shimatta.', 'Far from being praised, I got scolded.']],
    mistakes: ['Second clause often has も or さえ for "let alone".'],
    exercises: [{ type: 'fill', prompt: '薬を飲んだのに、治る＿、熱が上がった。', answer: 'どころか', choices: ['どころか', 'どころではない', 'ところで'], why: 'Opposite of expectation: どころか.' }] },
  { id: 'dokoro-de-wa-nai', unit: 28, title: '〜どころではない', pattern: '[V-dictionary / N] どころではない', summary: 'this is no time for', explanation: 'Circumstances make the activity out of the question.',
    ex: [['仕事が忙しくて、旅行どころではない。', 'しごとがいそがしくて、りょこうどころではない。', 'shigoto ga isogashikute, ryokou dokoro de wa nai.', 'Work is so busy that a trip is out of the question.'], ['熱があって、勉強するどころではなかった。', 'ねつがあって、べんきょうするどころではなかった。', 'netsu ga atte, benkyou suru dokoro de wa nakatta.', 'I had a fever and was in no state to study.'], ['地震の後は、花見どころではない。', 'じしんのあとは、はなみどころではない。', 'jishin no ato wa, hanami dokoro de wa nai.', 'After the earthquake, this is no time for blossom viewing.']],
    mistakes: ['Different from どころか (far from).'],
    exercises: [{ type: 'fill', prompt: '締め切りが明日なので、遊ぶ＿。', answer: 'どころではない', choices: ['どころではない', 'どころか', 'ところだった'], why: 'No time for: どころではない.' }] },
  { id: 'tokoro-datta', unit: 29, title: '〜ところだった', pattern: '[V-dictionary] ところだった', summary: 'almost (but did not)', explanation: 'Something nearly happened. Often with もう少しで or 危うく.',
    ex: [['もう少しで事故を起こすところだった。', 'もうすこしでじこをおこすところだった。', 'mou sukoshi de jiko o okosu tokoro datta.', 'I very nearly caused an accident.'], ['危うく電車に乗り遅れるところだった。', 'あやうくでんしゃにのりおくれるところだった。', 'ayauku densha ni noriokureru tokoro datta.', 'I almost missed the train.'], ['彼に言われなければ、忘れるところだった。', 'かれにいわれなければ、わすれるところだった。', 'kare ni iwarenakereba, wasureru tokoro datta.', 'If he had not told me, I would have forgotten.']],
    mistakes: ['Dictionary form before ところだった, not past.'],
    exercises: [{ type: 'fill', prompt: 'もう少しで財布を落とす＿。', answer: 'ところだった', choices: ['ところだった', 'ところだ', 'ところに'], why: 'Nearly happened: ところだった.' }] },
  { id: 'tokoro-ni', unit: 29, title: '〜ところに・〜ところへ・〜ところを', pattern: '[V-dictionary / V-ている / V-た] ところに / ところへ / ところを', summary: 'just when (interrupted)', explanation: 'At the moment of a state or action, something else happens, often with an effect on it.',
    ex: [['出かけようとしたところに、電話が鳴った。', 'でかけようとしたところに、でんわがなった。', 'dekakeyou to shita tokoro ni, denwa ga natta.', 'Just as I was about to go out, the phone rang.'], ['困っているところへ、友達が来てくれた。', 'こまっているところへ、ともだちがきてくれた。', 'komatte iru tokoro e, tomodachi ga kite kureta.', 'Just when I was in trouble, a friend came.'], ['お忙しいところをすみません。', 'おいそがしいところをすみません。', 'oisogashii tokoro o sumimasen.', 'Sorry to bother you when you are busy.']],
    mistakes: ['ところを is used when the moment is acted upon (見られた, 助けられた).'],
    exercises: [{ type: 'fill', prompt: '寝ようとしていた＿、友達から電話が来た。', answer: 'ところに', choices: ['ところに', 'ところだった', 'どころか'], why: 'Interrupted moment: ところに.' }] },
  { id: 'to-shitara', unit: 30, title: '〜としたら・〜とすれば・〜とすると', pattern: '[plain] としたら / とすれば / とすると', summary: 'supposing that; if we assume', explanation: 'Sets up a hypothesis and asks what follows from it.',
    ex: [['海外に住むとしたら、どこがいいですか。', 'かいがいにすむとしたら、どこがいいですか。', 'kaigai ni sumu to shitara, doko ga ii desu ka.', 'Supposing you lived abroad, where would be good?'], ['この話が本当だとすれば、大変なことだ。', 'このはなしがほんとうだとすれば、たいへんなことだ。', 'kono hanashi ga hontou da to sureba, taihen na koto da.', 'If this story is true, it is a serious matter.'], ['今から出るとすると、六時には着く。', 'いまからでるとすると、ろくじにはつく。', 'ima kara deru to suru to, rokuji ni wa tsuku.', 'If we leave now, we will arrive by six.']],
    mistakes: ['とすると often leads to a logical consequence; としたら to a question.'],
    exercises: [{ type: 'fill', prompt: '宝くじが当たった＿、何を買いますか。', answer: 'としたら', choices: ['としたら', 'として', 'とともに'], why: 'Hypothesis: としたら.' }] },
  { id: 'nai-koto-ni-wa', unit: 30, title: '〜ないことには', pattern: '[V-ない] ことには / [N で] ないことには', summary: 'unless; without first', explanation: 'Without the first thing, the second (negative) result holds.',
    ex: [['実際に見ないことには、判断できない。', 'じっさいにみないことには、はんだんできない。', 'jissai ni minai koto ni wa, handan dekinai.', 'Unless I see it in person, I cannot judge.'], ['努力しないことには、何も変わらない。', 'どりょくしないことには、なにもかわらない。', 'doryoku shinai koto ni wa, nani mo kawaranai.', 'Unless you make an effort, nothing will change.'], ['本人でないことには、手続きができません。', 'ほんにんでないことには、てつづきができません。', 'honnin de nai koto ni wa, tetsuzuki ga dekimasen.', 'Unless you are the person concerned, the procedure cannot be done.']],
    mistakes: ['Followed by a negative clause.'],
    exercises: [{ type: 'fill', prompt: '読んでみ＿、面白いかどうか分からない。', answer: 'ないことには', choices: ['ないことには', 'ないことはない', 'ないことなく'], why: 'Unless: ないことには.' }] }
];

